# Functions for the Steps of analysis.R (generated by targetfy).

# Read and clean ---------------------------------------------------------

clean_sales <- function(sales) {
  sales |>
    filter(year >= 2021) |>
    mutate(revenue = revenue / 1000)
}

# Revenue by region ------------------------------------------------------

summarise_by_region <- function(sales) {
  sales |>
    group_by(region) |>
    summarise(revenue = sum(revenue), .groups = "drop")
}

# Model ------------------------------------------------------------------

fit_revenue_model <- function(sales) {
  lm(revenue ~ region + year, data = sales)
}

tidy_model <- function(model) {
  broom::tidy(model)
}

# Outputs ----------------------------------------------------------------

plot_revenue <- function(by_region) {
  ggplot(by_region, aes(region, revenue)) +
    geom_col(fill = "steelblue")
}

save_plot <- function(plot, path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  ggsave(path, plot, width = 6, height = 4)
  path
}

save_coefs <- function(coefs, path) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  write_csv(coefs, path)
  path
}
